
<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowRight, Search, Van, CircleCheck, Clock, Box } from '@element-plus/icons-vue'
import { publicApi } from '@/api'
import type { Category, Medicine } from '@/types'
import MedicineCard from '@/components/MedicineCard.vue'
import SectionTitle from '@/components/SectionTitle.vue'

const router=useRouter();const categories=ref<Category[]>([]);const medicines=ref<Medicine[]>([]);const loading=ref(false);const keyword=ref('')
const load=async()=>{loading.value=true;try{[categories.value,medicines.value]=await Promise.all([publicApi.categories(),publicApi.medicines({page:1,size:8,sort:'default'}).then(v=>v.records)])}finally{loading.value=false}}
onMounted(load)
const search=()=>router.push({name:'category',query:keyword.value.trim()?{keyword:keyword.value.trim()}: {}})
</script>
